We summarize the proposed algorithm in Algorithm 1 and illustrate it in Figure 2.

```pseudo captionCount=0
\begin{algorithm}
\caption{\texttt{SpecDec++}}
\begin{algorithmic}
\REQUIRE draft model $q$, target model $p$, prefix $x_{\text{prefix}}$, acceptance prediction head $f_\theta$, threshold $h$.
            \STATE{\textbf{Initialize} the cumulative acceptance probability $\hat{p} = 1$}
            \FOR{$i=1$}
                \IF{$i>1$}
                    \STATE{Compute the final hidden embedding $\Hid_{i-1}$ of the token $y_{i-1}$.}
                \ENDIF
                \STATE{Compute $q_i = q(\cdot \mid x_{\text{prefix}}, y_1, \dots, y_{i-1})$.}
                \STATE{Sample $y_i \sim q_i$.}
                \STATE{Update $\hat{p} \gets \hat{p} \cdot \mathrm{sigmoid}(f_\theta(\Hid_{i-1}))$.}
                \IF{$1-\hat{p} > h$}
                    \STATE{\textbf{Break}}
                \ENDIF
            \ENDFOR
            \STATE{Let $K$ be the number of candidate tokens in the previous for-loop.}
            \STATE{ Compute \textit{in parallel} $p_i = p(\cdot \mid x_{\text{prefix}}, y_1, \dots, y_{i-1})$ for $i=1,\dots,K+1$. }
            \STATE{ Sample $r_1,\dots,r_K$ with $r_i \sim \mathrm{Unif}[0,1]$, $i=1,\dots,K$. }
            \STATE{ Compute the number of accepted tokens $n=\min\Big (\{i-1 \mid r_i \geq p_i(y_i)/q_i(y_i)\} \cup K \Big) $.}
    	\IF{$n < K$}
                \STATE{Sample $y'$ from the modified distribution $\mathrm{Norm}[(p_{n+1} - q_{n+1})_+]$ }
            \ELSE
                \STATE{Sample $y'$ from $p_{K+1}$}
            \ENDIF
            \STATE{\textbf{Return} $x_{\text{prefix}}, y_1,\dots,y_{n}, y'$}
\end{algorithmic}
\end{algorithm}
```

